  {"questionId": "B5-U1-Q127", "term": "Third Party", "definition": "An intermediary or subcontractor that provides a product or service in support of an organization."},
  {"questionId": "B5-U1-Q130", "term": "Vulnerability Scanning", "definition": "A mitigation that mimics malicious network activity to identify hosts open to attack."},
  {"questionId": "B5-U1-Q142", "term": "Supply Chain Security", "definition": "Efforts to enhance the security of the transport and logistics system for cargo."},
  {"questionId": "B5-U1-Q143", "term": "Third Party Data Storage", "definition": "An outside provider handling an organization data, which must be checked for securing it."},
  {"questionId": "B5-U2-Q092", "term": "Network Access Control", "definition": "A wired and wireless security solution that admits systems only after they meet predefined conditions; others go to a restricted network."},
  {"questionId": "B5-U2-Q093", "term": "Authentication", "definition": "The verification process in which a system confirms that individuals are who they say they are."},
  {"questionId": "B5-U2-Q094", "term": "Authentication Factors", "definition": "The kinds of proof a user can offer: something known, something held, a body trait, a location or a habit."},
  {"questionId": "B5-U2-Q095", "term": "Single Sign-On", "definition": "A method letting users log on once and gain access to several systems without providing additional credentials."},
  {"questionId": "B5-U2-Q096", "term": "802.1X", "definition": "A popular authentication protocol that lets a compliant switch and an authentication service verify clients before network access is permitted."},
  {"questionId": "B5-U2-Q097", "term": "Authentication, Authorization and Accounting", "definition": "Centralized services that verify users, grant them permitted tasks and log their network usage."},
  {"questionId": "B5-U2-Q098", "term": "Identification", "definition": "Presenting information about yourself to a system, such as a username or a smartcard."},
  {"questionId": "B5-U2-Q099", "term": "Authorization", "definition": "The step after verification that grants a user access to the network and the tasks the user is permitted to perform."},
  {"questionId": "B5-U2-Q102", "term": "TACACS+", "definition": "The protocol used in modern Cisco networks that replaced two older authentication services."},
  {"questionId": "B5-U2-Q103", "term": "Accounting", "definition": "Logs user activity on a network and tracks the resources a user consumes, such as access time and bandwidth."},
  {"questionId": "B5-U2-Q104", "term": "Application Security", "definition": "Protection that keeps software trustworthy, because one unsecure program can undo other defenses."},
  {"questionId": "B5-U2-Q105", "term": "Software Development Life Cycle", "definition": "The outline of an application's building process, divided into phases from requirements through maintenance."},
  {"questionId": "B5-U2-Q108", "term": "Cookies", "definition": "Small text files that websites store on client computers, holding user preferences and logon information."},
  {"questionId": "B5-U2-Q109", "term": "Scripting", "definition": "A list of commands performed by a program or engine, used to automate processes and generate web pages."},
  {"questionId": "B5-U2-Q110", "term": "Cross-Site Scripting", "definition": "A common attack that uses JavaScript to inject malicious code into a web application."},
  {"questionId": "B5-U2-Q111", "term": "Encryption", "definition": "Converting data to an unreadable format until an authorized person decrypts it back to readable cleartext."},
  {"questionId": "B5-U2-Q112", "term": "Intrusion Detection System", "definition": "Detects suspicious activity on a host or a network, logs it, and alerts administrators."},
  {"questionId": "B5-U2-Q113", "term": "Intrusion Prevention System", "definition": "Monitors hosts or networks for suspicious activity and takes corrective action to stop it."},
  {"questionId": "B5-U2-Q114", "term": "Host-Based Intrusion Detection System", "definition": "Intrusion detection on one host that displays notifications within the application or emails them for review."},
  {"questionId": "B5-U2-Q115", "term": "Complementary Metal-Oxide-Semiconductor", "definition": "The setup program that determines which storage device a computer boots from."},
  {"questionId": "B5-U2-Q116", "term": "Hardware Encryption", "definition": "Encryption done by chips physically installed in the system, applying very complex encryption more quickly than software."},
  {"questionId": "B5-U2-Q117", "term": "Full Disk Encryption", "definition": "Encrypting an entire hard disk drive so its contents stay protected if the drive is stolen or lost."},
  {"questionId": "B5-U2-Q118", "term": "Network-Based Intrusion Detection System", "definition": "A system, built from software or hardware, that analyzes all traffic crossing the network to monitor activity on multiple systems."},
  {"questionId": "B5-U2-Q128", "term": "Hardware Security Module", "definition": "An add-on device that stores cryptographic processors on a separate card installed on a system."},
  {"questionId": "B5-U2-Q130", "term": "Host-Based Intrusion Prevention System", "definition": "A host-based system that actively protects the host by stopping attacks."},
  {"questionId": "B5-U2-Q131", "term": "Application Vulnerabilities", "definition": "Weaknesses such as ActiveX controls that let websites take full access to a system."},
  {"questionId": "B5-U2-Q125", "term": "Trusted Platform Module", "definition": "The module that stores the cryptographic keys used to encrypt the data when an entire disk is encrypted."},
  {"questionId": "B5-U3-Q044", "term": "User Settings", "definition": "Group policy configurations that apply to a person on any machine they use and restrict what can be changed on the desktop."},
  {"questionId": "B5-U3-Q045", "term": "Active Directory", "definition": "Service that stores information about all network resources, such as servers, printers, user accounts, groups and security policies, across a domain."},
  {"questionId": "B5-U3-Q046", "term": "Computer Settings", "definition": "Group policy configurations that enforce password policies and restrict which software may run on a system."},
  {"questionId": "B5-U3-Q048", "term": "Access Control List", "definition": "Permissions set on files and folders so that only a specific group of users can reach them, which maintains confidentiality."},
  {"questionId": "B5-U3-Q049", "term": "New Technology File System", "definition": "Windows drive format with extra features such as permissions, which a storage drive must have before its folders can be secured."},
  {"questionId": "B5-U3-Q050", "term": "Full Control", "definition": "Folder or file permission that gives a user every possible permission, including changing the permissions of the file."},
  {"questionId": "B5-U3-Q052", "term": "Software-Based Firewall", "definition": "Program installed on a single computer or server to protect that one system; also called a host-based or personal firewall."},
  {"questionId": "B5-U3-Q053", "term": "Windows Firewall", "definition": "Software firewall that comes with Microsoft's desktop platform; it can allow programs through, change notification settings, turn on or off and restore defaults."},
  {"questionId": "B5-U3-Q054", "term": "Forward Proxy", "definition": "Proxy in which the client sends its request to the proxy, which retrieves the resource from the Internet and returns the response."},
  {"questionId": "B5-U3-Q056", "term": "Networking Access Control List", "definition": "Access list on a Cisco router that regulates inbound and outbound traffic; standard and extended are the two common types."},
  {"questionId": "B5-U3-Q058", "term": "Notifications", "definition": "Host-based firewall feature that shows a message when someone tries to connect or a program tries to send data out."},
  {"questionId": "B5-U3-Q059", "term": "Windows Firewall with Advanced Security", "definition": "Security Settings policy that configures the traffic filter built into Microsoft's desktop platform."},
  {"questionId": "B5-U4-Q020", "term": "Public Zone", "definition": "Any network not controlled by the network administrator; the Internet is the best and most popular example."},
  {"questionId": "B5-U4-Q021", "term": "Intranet Zone", "definition": "Another name for the private zone, where the local network resides and only authorized users have access."},
  {"questionId": "B5-U4-Q022", "term": "Wireless", "definition": "Separate zone for clients that connect without cables, letting the firewall administrator control which other zones they can access."},
  {"questionId": "B5-U4-Q025", "term": "Security Zones", "definition": "Network segments, divided by firewalls, that give overall protection to a network; the usual three are private, demilitarized and public."},
  {"questionId": "B5-U5-Q053", "term": "Computer Incident Response Team", "definition": "The group of staff with different skills that knows how to handle, correct and document security problems in an organization."},
  {"questionId": "B5-U5-Q054", "term": "Incident Response Plan", "definition": "Document every organization creates that defines incident types, member duties, reporting steps, exercises and user roles."},
  {"questionId": "B5-U5-Q055", "term": "Incident Categories", "definition": "Named types of security problems, such as social engineering or denial of service, that a plan defines so each can be recognized."},
  {"questionId": "B5-U5-Q056", "term": "Roles and Responsibilities", "definition": "Plan element defining each team member's job before, during and after a security problem."},
  {"questionId": "B5-U5-Q057", "term": "Reporting Requirements", "definition": "Plan element identifying when and how users must send word of potential security problems up to the right people."},
  {"questionId": "B5-U5-Q059", "term": "First Responder", "definition": "First individual notified of an incident, who takes charge of it and is a member of the response team."},
  {"questionId": "B5-U5-Q060", "term": "Event", "definition": "Any observable occurrence in a system or network, which sometimes signals that a harmful problem is under way."},
  {"questionId": "B5-U5-Q061", "term": "Incident", "definition": "Assessed occurrence that actually or potentially jeopardizes the confidentiality, integrity or availability of an information system."},
  {"questionId": "B5-U5-Q062", "term": "Incident Handling Process", "definition": "The six standard phases followed in response to cyber incidents, from detecting events to reviewing lessons learned afterward."},
  {"questionId": "B5-U5-Q063", "term": "Incident Analysis", "definition": "The series of analytical steps taken to find out what happened, including the root cause of what went wrong."},
  {"questionId": "B5-U5-Q064", "term": "Gather Information", "definition": "First analysis step in which involved personnel identify and collect relevant data such as logs, personal accounts and intelligence."},
  {"questionId": "B5-U5-Q065", "term": "Operational Impact", "definition": "Detrimental effects on an organization's ability to perform its mission, such as lost mission critical data or applications."},
  {"questionId": "B5-U5-Q066", "term": "Coordinate", "definition": "Analysis step of working with the victim system's owning support agencies to determine its Mission Assurance Category level."},
  {"questionId": "B5-U5-Q067", "term": "Courses of Action", "definition": "Planned responses to an incident that a postmortem may revise, explain after failure, or replace with new ones."},
  {"questionId": "B5-U5-Q070", "term": "Preliminary Analysis and Identification", "definition": "Second phase in which the activity is categorized and notification messages are sent."},
  {"questionId": "B5-U6-Q063", "term": "Cyber Hygiene", "definition": "Regular practices and steps that maintain system health and improve online security, like physical hygiene wards off deterioration."},
  {"questionId": "B5-U6-Q064", "term": "Virus Definitions", "definition": "Regularly updated information pushed out to users so antivirus software can protect their systems."},
  {"questionId": "B5-U6-Q065", "term": "Password", "definition": "A long, complex string of mixed characters that protects an account and should not be a dictionary word."},
  {"questionId": "B5-U6-Q066", "term": "Baseline Configuration", "definition": "The starting point for future assessments, created when a system is first built and representing how it should be configured."},
  {"questionId": "B5-U6-Q067", "term": "Configuration Management", "definition": "The process of maintaining computer systems, servers and software in a reliable, consistent state as changes are made over time."},
  {"questionId": "B5-U6-Q068", "term": "Disaster Recovery", "definition": "A benefit of configuration management in which assets are easily recoverable and systems can roll back to a previously working state."},
  {"questionId": "B5-U6-Q069", "term": "Redundant Array of Independent Disks", "definition": "A way to manage disk drives so two or more physical drives create one logical drive, safer and faster."},
  {"questionId": "B5-U6-Q071", "term": "Striping", "definition": "A method that divides portions of data between two drives at the same time, boosting performance."},
  {"questionId": "B5-U6-Q072", "term": "RAID 1", "definition": "A drive setup called mirroring in which all data saved to one drive is reflected on the other."},
  {"questionId": "B5-U6-Q074", "term": "Full Backup", "definition": "The backup type that copies all selected files and folders without relying on the archive bit."},
  {"questionId": "B5-U6-Q076", "term": "Incremental Backup", "definition": "A backup of changes since the previous backup that resets the archive flag, and normally the type used daily."},
  {"questionId": "B5-U6-Q077", "term": "Disaster Recovery Plan", "definition": "A document every department should develop with step-by-step instructions for recovering IT systems and data when a disaster strikes."},
  {"questionId": "B5-U6-Q078", "term": "Master Password", "definition": "The single long, strong secret that protects a password-management wallet and must not be duplicated on other accounts."},
  {"questionId": "B5-U7-Q085", "term": "Computer Security", "definition": "Air Force program protecting information system resources and information, focused on end-point security and ports, protocols and services management."},
  {"questionId": "B5-U7-Q087", "term": "Security Programs", "definition": "The five Air Force efforts that direct the goals and methods for protecting data, information systems, processes and technologies."},
  {"questionId": "B5-U7-Q088", "term": "CIA Triad", "definition": "The three fundamental goals of protecting information, taken together as one set. Not to be confused with a government intelligence agency."},
  {"questionId": "B5-U7-Q089", "term": "Confidentiality", "definition": "Fundamental goal ensuring only authorized persons can gain access to information and read it, using permissions and encryption."},
  {"questionId": "B5-U7-Q090", "term": "Access Control", "definition": "Setting permissions on files and folders, often through a list, so that only a specific group of users can reach them."},
  {"questionId": "B5-U7-Q091", "term": "Secure Area Access Control", "definition": "Physical security measures that lock network links in closets, keep classified systems in secure facilities and store removable media in approved safes."},
  {"questionId": "B5-U7-Q092", "term": "Steganography", "definition": "Method of hiding information, such as a text file, in a graphic file; the receiver uses a program to read it out."},
  {"questionId": "B5-U7-Q093", "term": "Integrity", "definition": "Fundamental goal ensuring data sent from a source arrives at its destination, or sits in storage, without having been altered."},
  {"questionId": "B5-U7-Q099", "term": "Availability", "definition": "Third fundamental goal, ensuring information can be used when the user wants it; often overlooked."},
  {"questionId": "B5-U7-Q100", "term": "Fault Tolerance", "definition": "Data redundancy solution in which multiple drives work together, so if one fails the other drives hold a copy of the information."},
  {"questionId": "B5-U7-Q101", "term": "Clustering", "definition": "High-availability solution in which multiple servers act as one unit, so if one fails another takes over the workload."},
  {"questionId": "B5-U7-Q102", "term": "Patching", "definition": "Keeping a system up to date with service packs and security hot fixes, which reduces its vulnerabilities and the chances of attack."},
  {"questionId": "B5-U7-Q105", "term": "Malicious Logic", "definition": "Also called malicious code: computer code, including viruses, spyware and steal-ware, written to cause problems and concealing itself until later."},
  {"questionId": "B5-U7-Q106", "term": "Fraud, Waste and Abuse", "definition": "Intentional deception meant to unlawfully deprive the Air Force of something of value, or to give an individual an unentitled benefit."},
  {"questionId": "B5-U7-Q108", "term": "TEMPEST", "definition": "Program, formerly called Emissions Security, that finds vulnerabilities in systems processing national security information that could lead to interceptable compromising emanations."},
  {"questionId": "B5-U7-Q109", "term": "TEMPEST Vulnerabilities", "definition": "Weaknesses arising from signals that electronic devices give off unintentionally, which people with the right equipment can intercept and exploit."},
  {"questionId": "B5-U7-Q110", "term": "Protected Distribution System", "definition": "Wire line or fiber-optic telecommunication system with adequate safeguards that permit sending unencrypted information; sometimes called a protective distribution system."},
  {"questionId": "B5-U7-Q112", "term": "Red/Black Separation", "definition": "Principle for keeping signals with sensitive plain-text information partitioned from signals carrying encrypted information in copper cabling systems."},
  {"questionId": "B5-U7-Q113", "term": "Information Protection", "definition": "Subset of the Air Force Security Enterprise made of three core disciplines covering personnel, industry and information."},
  {"questionId": "B5-U7-Q111", "term": "Hardened Distribution System", "definition": "The two categories are the heavily protected type with hardened conduit, alarms or constant viewing, and the simple type in any-material carrier."},
  {"questionId": "B5-U7-Q115", "term": "Information Security (INFOSEC)", "definition": "Core discipline within Information Protection that identifies and protects classified national security information and unclassified material needing controls, in line with policy."},
  {"questionId": "B5-U7-Q116", "term": "Freedom of Information Act (FOIA)", "definition": "Federal law since 1967 giving the public the right to request records from any federal agency, subject to nine exemptions."},
  {"questionId": "B5-U7-Q117", "term": "For Official Use Only (FOUO)", "definition": "Legacy marking for unclassified information expected to qualify for an exemption from mandatory public release, being replaced as the newer program is implemented."},
  {"questionId": "B5-U7-Q118", "term": "Controlled Unclassified Information (CUI)", "definition": "Government created or owned information that needs safeguarding or dissemination controls but is not classified; it is a designation, not a classification."},
  {"questionId": "B5-U7-Q119", "term": "Privacy Act of 1974", "definition": "Law that prescribes the management, access, handling and denial of access to personal records kept in an official system of records."},
  {"questionId": "B5-U7-Q120", "term": "Classified Information", "definition": "Information determined to require protection against unauthorized disclosure in the interest of national defense, because its release could damage national security."},
  {"questionId": "B5-U7-Q121", "term": "Top Secret", "definition": "Classification for national security information requiring the highest degree of protection, because unauthorized disclosure could cause exceptionally grave damage."},
  {"questionId": "B5-U7-Q122", "term": "Secret", "definition": "Classification for information requiring a substantial degree of protection, because unauthorized disclosure could cause serious damage to national security."},
  {"questionId": "B5-U7-Q123", "term": "Confidential", "definition": "Classification for information requiring less protection than the higher levels; disclosure could cause some damage to national security."},
  {"questionId": "B5-U7-Q124", "term": "General Services Administration (GSA)", "definition": "Agency that establishes and publishes standards and specifications for storage devices used to safeguard classified material."},
  {"questionId": "B5-U7-Q125", "term": "Operations Security (OPSEC)", "definition": "Process of identifying, analyzing and controlling critical information to reduce mission vulnerabilities and deny successful adversary collection and exploitation."},
  {"questionId": "B5-U7-Q126", "term": "Critical Information", "definition": "Fact about friendly intentions, capabilities and activities that adversaries vitally need to plan and act effectively against mission accomplishment."},
  {"questionId": "B5-U7-Q127", "term": "Indicator", "definition": "Friendly detectable action or open-source information that an adversary can interpret or piece together to derive critical information."},
  {"questionId": "B5-U7-Q128", "term": "Social Media", "definition": "Online sites and applications through which adversaries easily gather information about military operations; sensitive details should never be posted there."},
  {"questionId": "B5-U7-Q129", "term": "Communications Security (COMSEC)", "definition": "Program of measures and controls that denies unauthorized persons national security information from government information systems and ensures their authenticity."},
  {"questionId": "B5-U7-Q131", "term": "Decryption", "definition": "Restoration of encrypted data to its original plain text or other readily usable state, turning cipher text back into plain text."},
  {"questionId": "B5-U7-Q132", "term": "Cryptanalysis", "definition": "Science of trying to break a coding system so that the information can be revealed to an unauthorized user."},
  {"questionId": "B5-U7-Q133", "term": "Cryptosecurity", "definition": "Protection that results from the proper use of cryptographic systems, including both building a highly secure system and using it correctly."},
  {"questionId": "B5-U7-Q134", "term": "Transmission Security (TRANSEC)", "definition": "Measures that protect intentional transmissions from interception and exploitation by means other than cryptanalysis, chiefly by choosing a proper secured system."},
  {"questionId": "B5-U7-Q135", "term": "Physical Security", "definition": "Protection of sensitive cryptographic material through physical barriers, limited access and approved safes against improper destruction, handling and viewing."}
